result:
#instanceComplete,
#taskComplete {
    width: 100%;
    height: 120px;
    margin: 0 0 36px 0;
}

#instanceTaskTrend {
    width: 100%;
    height: 260px;
}

#instanceStatus {
    width: 100%;
    height: calc(100% - 116px);
}

.flex {
    display: flex;
    justify-content: space-between;
    align-content: center;
    align-items: center;
}

.borderTop {
    border-top: 1px solid #eaeaea;
}

.borderLeft {
    border-left: 1px solid #eaeaea;
}

.border-top-dashed {
    border-top: 1px dashed #eaeaea;
}

.content-box {
    width: calc(100% - 16px);
    height: calc(100% - 16px);
    margin: 8px;
    padding: 24px 24px 16px 24px;
    background: #fff;
    overflow: auto;
    border-radius: 4px;
}

.info-box {
    width: 100%;
    height: 434px;
}

.left-static-box {
    width: 75%;
    height: 100%;
    padding-right: 24px;
}

.static-show-info {
    padding-bottom: 16px;
}

.static-box {
    width: 24%;
    height: 88px;
    background: url('../../../assets/workflow/processTemplate.png') no-repeat;
    background-size: cover;
    border-radius: 4px;
    color: #ffffff;
    text-align: center;
    padding: 12px 0 10px 0;
}

.static-box.all-duration-box {
    background: url('../../../assets/workflow/processComplete.png') no-repeat;
}

.static-box.instance-box {
    background: url('../../../assets/workflow/processInstance.png') no-repeat;
}

.static-box.revoke-task-box {
    background: url('../../../assets/workflow/taskComplete.png') no-repeat;
}

.static-data {
    line-height: 42px;
    font-weight: 600;
    font-size: 30px;
}

.static-name {
    line-height: 22px;
    font-weight: 400;
    font-size: 16px;
}

.static-show-echarts {
    padding: 16px 0;
    width: 100%;
}

.gauge-echarts {
    width: 25%;
    height: 298px;
    padding: 0 24px;
    min-width: 289px;
    cursor: default;
    user-select: none;
}

.gauge-echarts:first-child {
    width: calc(25% - 25px);
    padding-left: 0;
    min-width: 264px;
}

.echarts-title {
    line-height: 30px;
    font-size: 16px;
    color: #333651;
    margin-bottom: 32px;
}

.gauge-legend {
    padding: 0 20px;
    line-height: 32px;
}

.value-label {
    font-size: 14px;
    color: #545672;
}

.value-icon {
    font-size: 10px;
    color: #545672;
}

.value-value {
    font-weight: 500;
    font-size: 14px;
    color: #333651;
}

.echarts-data {
    width: 103px;
}

.echarts-data-item {
    position: relative;
    height: 32px;
}

.mark {
    display: inline-block;
    vertical-align: middle;
    width: 8px;
    height: 8px;
    border-radius: 4px;
}

.yellow-mark {
    background: #f7ab2c;
}

.green-mark {
    background: #73deb3;
}

.mark-text {
    font-size: 12px;
    color: #545672;
    display: inline-block;
    margin-left: 8px;
    vertical-align: middle;
}

.count-data {
    font-size: 12px;
    color: #545672;
    display: inline-block;
    position: absolute;
    right: 0;
}

.line-echarts {
    width: calc(50% + 25px);
    height: 298px;
    padding-left: 24px;
}

.right-status-box {
    width: 25%;
    height: calc(100% - 16px);
    padding-left: 24px;
    min-width: 307px;
}

.pie-legend {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    align-content: center;
}

.pie-legend-item {
    width: 125px;
    font-weight: 400;
    font-size: 12px;
    color: #545672;
    line-height: 32px;
    position: relative;
    cursor: pointer;
    user-select: none;
}

.pie-legend-item-name {
    display: inline-block;
    margin-left: 10px;
}

.pie-legend-item-value.unactive,
.pie-legend-item-name.unactive {
    color: #cecece;
}

.pie-legend-item-value {
    display: inline-block;
    position: absolute;
    right: 0;
}

.pie-legend-item + .pie-legend-item {
    width: 157px;
    padding-left: 32px;
}

.split-line {
    width: 100%;
    height: 0;
}

.table-box {
    width: 100%;
    height: calc(100% - 434px);
    padding: 0;
    min-height: 300px;
}

.table-box ::v-deep (.el-table--scrollable-y .el-table__body-wrapper:hover),
.table-box ::v-deep (.el-table--scrollable-x .el-table__body-wrapper:hover) {
    overflow-x: hidden !important;
}

.pointer-box {
    cursor: pointer;
}
